50	// Resolve `path` to an absolute, EXISTING ELF. Returns the resolved string on
51	// success; on failure prints an error tagged with `ctx` and returns "". The
52	// existence check is here, at the one resolver fast/cycle/cycle-gdb share, so a
53	// missing path fails with a clear "ELF not found" instead of being handed to the
54	// engine (e.g. qemu's cryptic "Unable to find the RISC-V BIOS"). Mirrors the
55	// up-front check run_hybrid already does.
56	std::string abs_elf(const std::string& path, const std::string& ctx) {
57	  std::error_code ec;
58	  fs::path abs = fs::absolute(path, ec);
59	  if (ec) {
60	    std::fprintf(stderr, "andesim run %s: cannot resolve ELF '%s'\n",
61	                 ctx.c_str(), path.c_str());
62	    return "";
63	  }
64	  if (!fs::is_regular_file(abs, ec)) {
65	    std::fprintf(stderr, "andesim run %s: ELF not found: %s\n", ctx.c_str(),
66	                 path.c_str());
67	    return "";
68	  }
69	  return abs.string();
70	}
