72	// Validate the lone-ELF positional shape the standalone models require: print
73	// the diagnostic and return 2 on a violation, else 0. Split out so `cycle`
74	// can reject a missing/extra ELF BEFORE paying for engine discovery (which
75	// spawns a --describe subprocess per Verilator build). `model` labels the error.
76	int check_one_elf(const Cli& cli, const char* model) {
77	  if (cli.positional.empty()) {
78	    std::fprintf(stderr,
79	                 "andesim run --mode %s: missing ELF (the workload to run; "
80	                 "e.g. a tests/fixtures/<name>.elf)\n",
81	                 model);
82	    return 2;
83	  }
84	  if (cli.positional.size() > 1) {
85	    std::fprintf(stderr,
86	                 "andesim run --mode %s: unexpected argument '%s' "
87	                 "(engine args go after --)\n",
88	                 model, cli.positional[1].c_str());
89	    return 2;
90	  }
91	  return 0;
92	}
