170	// `run --mode fast`: QEMU alone, functional, transparent passthrough. Needs
171	// only the built-in qemu descriptor, so it resolves that directly rather than
172	// discover_engines(), which would spawn a --describe subprocess per Verilator
173	// build only to discard them all here.
174	int run_fast(const Cli& cli) {
175	  // fast is QEMU-only; an explicit engine must name 'qemu64' (rv64) or 'qemu32'.
176	  if (!cli.engine.empty() && cli.engine != kQemuId64 && cli.engine != kQemuId32) {
177	    std::fprintf(stderr,
178	                 "andesim run --mode fast: engine must be 'qemu64' or 'qemu32', "
179	                 "got '%s'\n",
180	                 cli.engine.c_str());
181	    return 2;
182	  }
183	  // --runtime linux (U2, ROADMAP_LINUX_RUNTIME.md) defaults --mem-size to 1G
184	  // (the app + vlinux's own arenas) when the user did not pick one.
185	  std::string mem_size_spec = cli.mem_size;
186	  if (cli.runtime == "linux" && mem_size_spec.empty()) mem_size_spec = "1G";
187	
188	  // --mem-size forwards a plain `-m`; QEMU validates it (as-is, no mmap, no
189	  // default injected). It precedes the post-`--` args, so a user's own -m wins.
190	  std::string err;
191	  std::vector<std::string> extra = qemu_m_args(mem_size_spec, err);
192	  if (!err.empty()) {
193	    std::fprintf(stderr, "andesim run --mode fast: %s\n", err.c_str());
194	    return 2;
195	  }
196	  // --gdb: inject QEMU's built-in GDB stub and pause at startup.
197	  if (cli.gdb) {
198	    const std::string port = cli.gdb_port.empty() ? "1234" : cli.gdb_port;
199	    extra.push_back("-gdb");
200	    extra.push_back("tcp::" + port);
201	    extra.push_back("-S");
202	  }
203	
204	  // --runtime linux: stage a manifested vlinux.elf that boots the app under
205	  // the proxy kernel. The ELF positional is the APP, not the boot image --
206	  // -bios loads the staged vlinux instead (run_standalone's boot_elf_override).
207	  Cli cli2 = cli;
208	  std::string boot_elf;
209	  if (cli.runtime == "linux") {
210	    if (int rc = check_one_elf(cli, "fast")) return rc;
211	    const std::string app_elf =
212	        abs_elf(cli.positional[0], "--mode fast --runtime linux");
213	    if (app_elf.empty()) return 2;
214	
215	    // mem_size_spec already passed qemu_m_args above (whole-MiB check, a
216	    // strictly tighter validation than parse_size alone), so this call
217	    // cannot fail: reused only to get the byte count for the manifest.
218	    const long long mem_bytes = parse_size(mem_size_spec, err);
219	
220	    std::string stage_err;
221	    boot_elf = stage_linux_runtime(app_elf, static_cast<uint64_t>(mem_bytes),
222	                                   cli.passthrough, stage_err);
223	    if (boot_elf.empty()) {
224	      std::fprintf(stderr, "andesim run --mode fast --runtime linux: %s\n",
225	                   stage_err.c_str());
226	      return 2;
227	    }
228	    log_line(kLogInfo, "[andesim] --runtime linux: staged %s (app=%s)",
229	             boot_elf.c_str(), app_elf.c_str());
230	
231	    // App argv (ROADMAP_LINUX_RUNTIME.md U8) travels through the manifest
232	    // above, not QEMU's own CLI -- clear it here so QEMU never sees it as
233	    // engine flags (e.g. "-m x.gguf" is not a memory size).
234	    cli2.passthrough.clear();
235	
236	    // Engine-synced CPU: the app + vlinux run on the hardware a hybrid
237	    // measurement targets, not the ax46 vplat default (last -cpu wins).
238	    extra.push_back("-cpu");
239	    extra.push_back("andes-ax45mpv,vlen=512");
240	  }
241	
242	  // Pick rv32 vs rv64. An explicit --engine (qemu32/qemu64) wins; otherwise read
243	  // the ELF's class so an rv32 program lands on qemu-system-riscv32 instead of
244	  // the rv64 default. Warn (do not fail) if an explicit choice contradicts the
245	  // ELF -- the override is the user's call.
246	  const int elf_w = cli.positional.empty() ? 0 : elf_xlen(cli.positional[0]);
247	  int xlen;
248	  if (cli.engine == kQemuId32) xlen = 32;
249	  else if (cli.engine == kQemuId64) xlen = 64;
250	  else xlen = elf_w ? elf_w : 64;  // no explicit engine: follow the ELF (else rv64)
251	  // Only an explicit engine can disagree with the ELF (when none is given, xlen
252	  // == elf_w), so this guard already implies an explicit --engine.
253	  if (elf_w && elf_w != xlen)
254	    std::fprintf(stderr,
255	                 "[andesim] --mode fast: --engine %s is rv%d but the ELF is rv%d "
256	                 "(running as rv%d)\n",
257	                 cli.engine.c_str(), xlen, elf_w, xlen);
258	  return run_standalone(cli2, builtin_qemu_arch(xlen), "fast", extra,
259	                        /*clean_output=*/false, boot_elf);
260	}
