262	// Block until 127.0.0.1:`port` is LISTENing (or `timeout_ms` elapses). vsim opens
263	// its --jtag-port only after it has reset and halted the hart, so the debugger we
264	// exec next must not race ahead of it -- OpenOCD/ICEman do not retry the bitbang
265	// connect, and a missed connect leaves the session dead. Non-intrusive: scans
266	// /proc/net/tcp rather than connecting (a probe connection would land in vsim's
267	// single debugger slot). Returns false on timeout.
268	static bool wait_for_jtag_port(uint16_t port, int timeout_ms = 20000) {
269	  constexpr int kPollMs = 50;
270	  for (int waited = 0; waited <= timeout_ms; waited += kPollMs) {
271	    if (std::FILE* f = std::fopen("/proc/net/tcp", "re")) {
272	      char line[512];
273	      while (std::fgets(line, sizeof line, f)) {
274	        // cols: sl  local_address(IP:port hex)  rem_address  st  ...
275	        // "%*8x:%x" skips the 8-hex-digit IPv4 and reads the local port; the
276	        // 0A (TCP_LISTEN) filter also drops the non-hex header row.
277	        unsigned lport = 0, st = 0;
278	        if (std::sscanf(line, "%*s %*8x:%x %*s %x", &lport, &st) == 2
279	            && st == 0x0A && lport == port) {
280	          std::fclose(f);
281	          return true;
282	        }
283	      }
284	      std::fclose(f);
285	    }
286	    std::this_thread::sleep_for(std::chrono::milliseconds(kPollMs));
287	  }
288	  return false;
289	}
