343	// `run --mode cycle`: one cycle-accurate engine alone, from reset (no QEMU,
344	// no --resume-from-qemu), transparent passthrough -- cycles surface in the
345	// engine's own output. Unlike fast, this must discover the Verilator build(s)
346	// to resolve the engine (explicit --engine, else the sole one).
347	int run_accurate(const Cli& cli) {
348	  // Reject a missing/extra ELF before discovery so a CLI typo does not spawn a
349	  // --describe subprocess per Verilator build only to fail on the argument.
350	  if (int rc = check_one_elf(cli, "cycle")) return rc;
351	  // --mem-size is validated but has nothing to size: the cycle engine always
352	  // models its full DRAM window. Say so instead of silently ignoring it.
353	  if (!cli.mem_size.empty()) {
354	    std::string se;
355	    if (parse_size(cli.mem_size, se); !se.empty()) {
356	      std::fprintf(stderr, "andesim run --mode cycle: --mem-size: %s\n",
357	                   se.c_str());
358	      return 2;
359	    }
360	    log_line(kLogWarn,
361	             "[andesim] --mem-size: the cycle engine models its full "
362	             "DRAM window; nothing to size");
363	  }
364	  Discovery disc = discover_engines();
365	  std::string err;
366	  const EngineDescriptor* eng =
367	      resolve_accurate_engine(disc.engines, cli.engine, err);
368	  if (!eng) {
369	    std::fprintf(stderr, "andesim run --mode cycle: %s\n", err.c_str());
370	    // Surface why an expected engine may be absent (failed --describe, etc.).
371	    for (const std::string& w : disc.warnings)
372	      std::fprintf(stderr, "andesim: skipped engine: %s\n", w.c_str());
373	    return 2;
374	  }
375	  // The ELF must match the engine's width: an rv32 ELF on an rv64 engine (or
376	  // vice versa) cannot run. Catch it here with a clear message instead of the
377	  // engine's cryptic "not of ELFCLASSxx". check_one_elf above guaranteed a lone
378	  // positional.
379	  if (std::string e = elf_engine_arch_error(cli.positional[0], *eng); !e.empty()) {
380	    std::fprintf(stderr, "andesim run --mode cycle: %s\n", e.c_str());
381	    return 2;
382	  }
383	  // --dry-run previews the standalone command and spawns nothing, so it takes
384	  // precedence over the interactive --gdb path (a dry run launches no debugger).
385	  if (cli.gdb && !cli.dry_run) return run_cycle_gdb(cli, *eng);
386	  // clean_output: hide vsim's banner + [info] log, restate the cycle count under
387	  // [andesim] (fast keeps raw passthrough -- QEMU has no such banner and its
388	  // monitor/gdbstub are interactive).
389	  return run_standalone(cli, *eng, "cycle", /*extra=*/{}, /*clean_output=*/true);
390	}
