740	int cmd_run(const Cli& cli) {
741	  if (cli.model.empty()) {
742	    std::fprintf(stderr,
743	                 "andesim run: --mode fast|cycle|hybrid is required "
744	                 "(pick the composition; see 'andesim run --help')\n");
745	    return 2;
746	  }
747	  if (!find_model(cli.model)) {
748	    std::fprintf(stderr,
749	                 "andesim run: unknown model '%s' (want fast|cycle|hybrid)\n",
750	                 cli.model.c_str());
751	    return 2;
752	  }
753	  // --runtime selects a proxy-kernel payload atop the chosen model
754	  // (ROADMAP_LINUX_RUNTIME.md). Only "linux" exists, and only --mode fast
755	  // and hybrid are wired (U2, U9) -- cycle has no roadmap need for it.
756	  if (!cli.runtime.empty() && cli.runtime != "linux") {
757	    std::fprintf(stderr, "andesim run: unknown --runtime '%s' (want 'linux')\n",
758	                 cli.runtime.c_str());
759	    return 2;
760	  }
761	  if (!cli.runtime.empty() && cli.model != "fast" && cli.model != "hybrid") {
762	    std::fprintf(stderr,
763	                 "andesim run: --runtime linux is supported only with "
764	                 "--mode fast or hybrid (not cycle)\n");
765	    return 2;
766	  }
767	  if (!cli.gdb_port.empty() && !cli.gdb) {
768	    std::fprintf(stderr, "andesim run: --gdb-port requires --gdb\n");
769	    return 2;
770	  }
771	  // --gdb is an interactive debugging aid; the hybrid handoff runs QEMU1 then
772	  // vsim sequentially in a pipeline and cannot pause for a debugger to attach.
773	  if (cli.gdb && cli.model == "hybrid") {
774	    std::fprintf(stderr,
775	                 "andesim run: --gdb is not supported with --mode hybrid\n");
776	    return 2;
777	  }
778	  // --print-memmap prints the HYBRID composition's guest memory map (the
779	  // regions both engines support across the handoff); fast/cycle run one
780	  // engine's native map, which andesim does not model.
781	  if (cli.print_memmap && cli.model != "hybrid") {
782	    std::fprintf(stderr,
783	                 "andesim run: --print-memmap requires --mode hybrid (it "
784	                 "prints the hybrid-supported guest memory map)\n");
785	    return 2;
786	  }
787	  // --verify re-runs the workload against a QEMU oracle -- only the hybrid
788	  // composition has a second engine to check.
789	  if (cli.verify && cli.model != "hybrid") {
790	    std::fprintf(stderr,
791	                 "andesim run: --verify requires --mode hybrid (the %s "
792	                 "model has nothing to cross-check)\n",
793	                 cli.model.c_str());
794	    return 2;
795	  }
796	  // Post-`--` args are forwarded verbatim to the engine -- but hybrid has TWO
797	  // legs (a QEMU fast-forward + a vsim measure leg) whose command lines the
798	  // handoff builds itself, so there is no single "the engine" to forward to.
799	  // Reject rather than silently drop (the old behavior) or guess a leg. vsim
800	  // options have dedicated flags (--kanata/--objdump); fast/cycle still forward.
801	  // Exception: --runtime linux's `-- <args>` are APP argv (ROADMAP_LINUX_RUNTIME.md
802	  // U8/U9), not engine flags for either leg -- they thread into the manifest
803	  // both legs' staged vlinux-run.elf shares, so they are meaningful here too.
804	  if (!cli.passthrough.empty() && cli.model == "hybrid" && cli.runtime != "linux") {
805	    std::fprintf(stderr,
806	                 "andesim run: --mode hybrid takes no `-- <args>` (the handoff "
807	                 "builds both legs' command lines; use --kanata/--objdump for "
808	                 "vsim options, or --mode fast|cycle to forward to one engine)\n");
809	    return 2;
810	  }
811	  // --trigger / --pc-start / --pc-end delimit the hybrid ROI window. --trigger
812	  // is hybrid-only; --pc-start/--pc-end belong to --trigger pc specifically. Any
813	  // other mode/trigger would SILENTLY drop them and hand back a figure for the
814	  // wrong window (fast/cycle: the whole program; hybrid+marker: the marker
815	  // window), so reject instead of measuring something the user did not ask for.
816	  if (!cli.trigger.empty() && cli.model != "hybrid") {
817	    std::fprintf(stderr,
818	                 "andesim run: --trigger applies only to --mode hybrid "
819	                 "(the ROI delimiter); fast/cycle run the whole program\n");
820	    return 2;
821	  }
822	  if (!cli.pc_end.empty() && cli.trigger != "pc") {
823	    std::fprintf(stderr,
824	                 "andesim run: --pc-end applies only to --mode hybrid "
825	                 "--trigger pc\n");
826	    return 2;
827	  }
828	  if (!cli.pc_start.empty() && cli.trigger != "pc") {
829	    std::fprintf(stderr,
830	                 "andesim run: --pc-start applies only to --mode hybrid "
831	                 "--trigger pc\n");
832	    return 2;
833	  }
834	  if (cli.model == "fast") return run_fast(cli);
835	  if (cli.model == "cycle") return run_accurate(cli);
836	  return run_hybrid(cli);  // model validated above; only hybrid remains
837	}
